    JsonDocument doc;
    if (deserializeJson(doc, msg)) return;
    if (!doc["x"].is<float>() || !doc["y"].is<float>()) return;
    joy_{{INDEX}}_x = doc["x"].as<float>();
    joy_{{INDEX}}_y = doc["y"].as<float>();
  } else {
    joy_{{INDEX}}_command = msg; // Button mode: user-configured direction/release payload.
  }
  // TODO: connect parsed coordinates/command to your GPIO or motor driver.
}

