PALETTE_CTRL.receiver_logic:
if (topic == "{{TOPIC}}") {
  if (msg.startsWith("#") && msg.length() == 7) {
    for (int i = 1; i < 7; ++i) if (!isxdigit(msg[i])) return;
    pal_{{INDEX}}_r = strtol(msg.substring(1, 3).c_str(), NULL, 16);
    pal_{{INDEX}}_g = strtol(msg.substring(3, 5).c_str(), NULL, 16);
    pal_{{INDEX}}_b = strtol(msg.substring(5, 7).c_str(), NULL, 16);
  } else {
    JsonDocument doc;
    if (deserializeJson(doc, msg)) return;
    if (doc["r"].is<int>() && doc["g"].is<int>() && doc["b"].is<int>()) {
      pal_{{INDEX}}_r = constrain(doc["r"].as<int>(), 0, 255);
      pal_{{INDEX}}_g = constrain(doc["g"].as<int>(), 0, 255);
      pal_{{INDEX}}_b = constrain(doc["b"].as<int>(), 0, 255);
    } else if (doc["h"].is<float>() && doc["s"].is<float>() && doc["v"].is<float>()) {
      float h = fmodf(constrain(doc["h"].as<float>(), 0.0f, 360.0f), 360.0f) / 60.0f;
      float s = constrain(doc["s"].as<float>(), 0.0f, 100.0f) / 100.0f;
      float v = constrain(doc["v"].as<float>(), 0.0f, 100.0f) / 100.0f;
      float c = v * s, x = c * (1.0f - fabsf(fmodf(h, 2.0f) - 1.0f)), m = v - c;
      float r = 0, g = 0, b = 0;
      if (h < 1) { r = c; g = x; } else if (h < 2) { r = x; g = c; }
      else if (h < 3) { g = c; b = x; } else if (h < 4) { g = x; b = c; }
      else if (h < 5) { r = x; b = c; } else { r = c; b = x; }
      pal_{{INDEX}}_r = (int)((r + m) * 255.0f + 0.5f);
      pal_{{INDEX}}_g = (int)((g + m) * 255.0f + 0.5f);
      pal_{{INDEX}}_b = (int)((b + m) * 255.0f + 0.5f);
    } else return;
  }
  // TODO: write RGB values to your LED driver.
}

